,
normalized as (
  select
    erp_private.freight_norm(carrier) carrier_code,
    erp_private.freight_city_key(destination_city) city_key,
    erp_private.freight_department_key(destination_department) department_key,
    destination_city city_name,
    destination_department department_name,
    sample_count::integer,
    weight_sample_count::integer,
    weight_p20::numeric,weight_p50::numeric,weight_p80::numeric,
    cost_p20::numeric,cost_p50::numeric,cost_p80::numeric,
    transit_sample_count::integer,
    transit_p50_days::numeric,transit_p80_days::numeric,
    source_start::date,source_end::date
  from raw
),
department_by_city as (
  select
    city_key,
    coalesce(max(nullif(department_key,'')),'UNKNOWN') department_key,
    coalesce(max(nullif(department_name,'')),'Sin departamento') department_name,
    max(city_name) city_name
  from normalized
  group by city_key
)
insert into erp_supply.freight_destinations(
  country_code,department_key,department_name,city_key,city_name,metadata
)
select
  'CO',department_key,department_name,city_key,city_name,
  jsonb_build_object('source','FREIGHT_HISTORICAL_2026')
from department_by_city
on conflict(country_code,department_key,city_key)
do update set
  department_name=excluded.department_name,
  city_name=excluded.city_name,
  active=true;

insert into erp_supply.freight_carriers(
  organization_id,code,name,metadata
)
select
  o.id,c.code,c.name,jsonb_build_object('source','FREIGHT_HISTORICAL_2026')
from erp_supply.organizations o
cross join (
  values
    ('COLVANES','Colvanes'),
    ('TCC','TCC'),
    ('VELOENVIOS','Veloenvíos')
) c(code,name)
where o.code='EI'
on conflict(organization_id,code)
do update set name=excluded.name,active=true;

