,
normalized as (
  select
    erp_private.freight_norm(carrier) carrier_code,
    erp_private.freight_city_key(destination_city) city_key,
    erp_private.freight_department_key(destination_department) department_key,
    sample_count::integer,
    weight_sample_count::integer,
    weight_p20::numeric,weight_p50::numeric,weight_p80::numeric,
    cost_p20::numeric,cost_p50::numeric,cost_p80::numeric,
    transit_sample_count::integer,
    transit_p50_days::numeric,transit_p80_days::numeric,
    source_start::date,source_end::date
  from raw
),
resolved as (
  select
    n.*,
    coalesce(
      nullif(n.department_key,''),
      max(nullif(n.department_key,'')) over(partition by n.city_key),
      'UNKNOWN'
    ) resolved_department
  from normalized n
),
grouped as (
  select
    carrier_code,city_key,resolved_department,
    sum(sample_count)::integer sample_count,
    sum(weight_sample_count)::integer weight_sample_count,
    sum(weight_p20*weight_sample_count)/nullif(sum(weight_sample_count),0) weight_p20,
    sum(weight_p50*weight_sample_count)/nullif(sum(weight_sample_count),0) weight_p50,
    sum(weight_p80*weight_sample_count)/nullif(sum(weight_sample_count),0) weight_p80,
    sum(cost_p20*sample_count)/nullif(sum(sample_count),0) cost_p20,
    sum(cost_p50*sample_count)/nullif(sum(sample_count),0) cost_p50,
    sum(cost_p80*sample_count)/nullif(sum(sample_count),0) cost_p80,
    sum(transit_sample_count)::integer transit_sample_count,
    sum(transit_p50_days*transit_sample_count)/nullif(sum(transit_sample_count),0)
      transit_p50_days,
    sum(transit_p80_days*transit_sample_count)/nullif(sum(transit_sample_count),0)
      transit_p80_days,
    min(source_start) source_start,
    max(source_end) source_end
  from resolved
  group by carrier_code,city_key,resolved_department
)
insert into erp_supply.freight_historical_aggregates(
  organization_id,model_version,origin_city_key,route_code,
  carrier_id,destination_id,
  sample_count,weight_sample_count,weight_p20,weight_p50,weight_p80,
  cost_p20,cost_p50,cost_p80,
  transit_sample_count,transit_p50_days,transit_p80_days,
  source_start,source_end,source_label
)
select
  o.id,'LEGACY_AGGREGATE_2026_09','TULUA','NATIONAL_DISPATCH',
  c.id,d.id,
  g.sample_count,g.weight_sample_count,g.weight_p20,g.weight_p50,g.weight_p80,
  g.cost_p20,g.cost_p50,g.cost_p80,
  g.transit_sample_count,g.transit_p50_days,g.transit_p80_days,
  g.source_start,g.source_end,'TRANSPORTADORAS_ENE_SEP_2026_AGGREGATED'
from grouped g
join erp_supply.organizations o on o.code='EI'
join erp_supply.freight_carriers c
  on c.organization_id=o.id and c.code=g.carrier_code
join erp_supply.freight_destinations d
  on d.country_code='CO'
 and d.city_key=g.city_key
 and d.department_key=g.resolved_department
on conflict(organization_id,model_version,route_code,carrier_id,destination_id)
do update set
  sample_count=excluded.sample_count,
  weight_sample_count=excluded.weight_sample_count,
  weight_p20=excluded.weight_p20,
  weight_p50=excluded.weight_p50,
  weight_p80=excluded.weight_p80,
  cost_p20=excluded.cost_p20,
  cost_p50=excluded.cost_p50,
  cost_p80=excluded.cost_p80,
  transit_sample_count=excluded.transit_sample_count,
  transit_p50_days=excluded.transit_p50_days,
  transit_p80_days=excluded.transit_p80_days,
  source_start=excluded.source_start,
  source_end=excluded.source_end,
  source_label=excluded.source_label;

commit;
